sys_script.script:
(function executeRule(current, previous) {
    var status = current.getValue('status');

    // If status is Rejected, dispatch_rejection_reason must be populated
    if (status === 'rejected') {
        var reason = current.getValue('dispatch_rejection_reason');
        if (!reason || reason.trim() === '') {
            gs.addErrorMessage('Dispatch Rejection Reason is required when status is Rejected.');
            current.setAbortAction(true);
            return;
        }
    }

    // Record dispatcher info when a dispatch decision is made (Accepted or Rejected)
    if (status === 'accepted' || status === 'rejected') {
        // Only set if not already set, or if status just changed to this value
        var previousStatus = previous ? previous.getValue('status') : '';
        if (previousStatus !== status) {
            current.setValue('dispatch_decided_by', gs.getUserID());
            current.setValue('dispatch_decided_on', new GlideDateTime());
        }
    }
})(current, previous);
